// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;

    function setUp() public { c = new keepMyEther(); }

    // Fuzz parameters: two deposit amounts and an attacker boolean controlling whether caller is adversarial
    function testFuzz_property(uint128 depositA, uint128 depositB, bool attackerIsCaller) public {
        // Keep amounts reasonable but wide
        uint256 amtA = uint256(depositA) % 1 ether; // [0,1e18)
        uint256 amtB = uint256(depositB) % 1 ether;

        // Two actors
        address acctA = vm.addr(1);
        address acctB = vm.addr(2);

        // Fund actors so they can deposit
        vm.deal(acctA, 5 ether);
        vm.deal(acctB, 5 ether);

        // If attackerIsCaller, deploy a ReentrantAttacker that will re-enter c.withdraw once when it receives funds
        ReentrantAttacker attacker;
        address caller;
        if (attackerIsCaller) {
            attacker = new ReentrantAttacker(c, acctA);
            caller = address(attacker);
            // give attacker eth so it can be msg.sender for deposit
            vm.deal(caller, 5 ether);
        } else {
            caller = acctA;
        }

        // acctB is a benign depositor
        // perform deposits: acctA (or attacker) and acctB
        if (caller == address(attacker)) {
            // attacker sends deposit by calling fallback of C
            vm.prank(caller);
            (bool okA, ) = address(c).call{value: amtA}("");
            require(okA);
        } else {
            vm.prank(acctA);
            (bool okA, ) = address(c).call{value: amtA}("");
            require(okA);
        }

        vm.prank(acctB);
        (bool okB, ) = address(c).call{value: amtB}("");
        require(okB);

        // At this point, contract balance should equal amtA+amtB
        // Record on-chain balances via public getter
        uint256 storedA = c.balances(caller == address(attacker) ? address(attacker) : acctA);
        uint256 storedB = c.balances(acctB);
        uint256 storedSumBefore = storedA + storedB;
        assert(address(c).balance == storedSumBefore);

        // Now trigger withdraw from caller. If caller is the attacker contract, its receive will re-enter once.
        bool ok;
        vm.prank(caller);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdraw, the correct contract maintains consistency between stored balances sum and address(c).balance.
        // The mutant can allow reentrancy to misalign stored balances with the eth actually held.
        uint256 newStoredA = c.balances(caller == address(attacker) ? address(attacker) : acctA);
        uint256 newStoredB = c.balances(acctB);
        uint256 storedSumAfter = newStoredA + newStoredB;
        uint256 ethBalanceAfter = address(c).balance;

        // General invariant: for ALL inputs the reference contract preserves that the sum of stored balances equals contract ether balance
        // We assert that equality; the mutant (zero-before-call) can be re-entered to violate it for some inputs
        assertTrue(storedSumAfter == ethBalanceAfter);
    }
}

// Minimal reentrant attacker: on receive, it will call withdraw() on c exactly once.
contract ReentrantAttacker {
    keepMyEther public c;
    address public beneficiary;
    bool private entered;

    constructor(keepMyEther _c, address _beneficiary) payable {
        c = _c;
        beneficiary = _beneficiary;
        entered = false;
    }

    // record receive and re-enter exactly once
    receive() external payable {
        if (!entered) {
            entered = true;
            // try to re-enter c.withdraw; this uses this contract as msg.sender
            try c.withdraw() {
                // ignore
            } catch {
                // ignore
            }
        }
        // forward received ETH to beneficiary so test actors keep funds (not strictly necessary)
        payable(beneficiary).transfer(address(this).balance);
    }
}
